mapper.select:
SELECT 
FROM exercise_item
WHERE EXISTS (
    SELECT 1 FROM health_resource_favorite f
    WHERE f.user_id = #{userId}
      AND f.resource_type = 'EXERCISE'
      AND f.resource_id = (CAST(exercise_item.id AS CHAR) COLLATE utf8mb4_unicode_ci)
)
ORDER BY plan_ready DESC, name, source_id
LIMIT #{offset}, #{size}
